REPO = Path(__file__).resolve().parents[2]
OUT = os.environ.get('ALTAI_OUT', str(REPO / 'data' / 'dataset_v3')) + '/'
o = pd.read_pickle(OUT + 'objects.pkl')
P, W, SS, RCL, RCW, gva, geo = o['P'], o['W'], o['SS'], o['RCL'], o['RCW'], o['gva'], o['geo']

