src = P.groupby(['group', 'indicator', 'unit', 'source']).agg(год_с=('year', 'min'), год_по=('year', 'max'), МО=('oktmo', 'nunique'), примечание=('note', 'first')).reset_index()

path = OUT + 'altai_dataset_v3.xlsx'
with pd.ExcelWriter(path, engine='openpyxl') as xw:
    sheets = {'README': readme, 'Показатели_источники': src, 'МО_сводка': W, 'МО_панель': P, 'НП': SS,
              'Регионы_сравнение': RCW, 'Регионы_ряды': RCL, 'ВДС_структура': gva}
    for name, df in sheets.items():
        df.to_excel(xw, sheet_name=name, index=False)
        ws = xw.sheets[name]
        ws.freeze_panes = 'B2' if name != 'README' else 'A2'
        for i, col in enumerate(df.columns, 1):
            q = df[col].astype(str).str.len().quantile(0.9) if len(df) else 10
            q = 10 if pd.isna(q) else q
            width = min(60, max(10, int(q), len(str(col)) // 2 + 4))
            ws.column_dimensions[get_column_letter(i)].width = width
os.makedirs(OUT + 'geo', exist_ok=True)
for k, df in geo.items():
    df.to_csv(OUT + f'geo/{k}.csv', index=False, sep=';', encoding='utf-8-sig')
P.to_csv(OUT + 'mo_panel_long.csv', index=False, sep=';', encoding='utf-8-sig')
W.to_csv(OUT + 'mo_summary.csv', index=False, sep=';', encoding='utf-8-sig')
SS.to_csv(OUT + 'settlements.csv', index=False, sep=';', encoding='utf-8-sig')
print({k: len(v) for k, v in sheets.items()}, {k: len(v) for k, v in geo.items()})
